-- F-230: characters on a baked accessory colour move to its clean colour + that accessory (customization 5).
-- Round 5: the human Cultist spiked harness (colours 20-23).
-- GENERATED by Scripts/Character Skins/accessories.py - do not edit, re-run the script. Idempotent: the
-- customization is stored first, keyed by the baked colour, then the colour moves.
-- Human Female 20 -> 30 + Accessories 1 (Spiked harness, emerald)
INSERT INTO character_customizations (guid, customization, choice) SELECT guid, 5, 1 FROM characters WHERE race = 1 AND gender = 1 AND skin = 20 ON DUPLICATE KEY UPDATE choice = 1;
UPDATE characters SET skin = 30 WHERE race = 1 AND gender = 1 AND skin = 20;
